--- /dev/null
+++ b/src/sign-session.ts
@@ -0,0 +1,76 @@
+import crypto from "crypto";
+
+const secret = process.env.SESSION_SIGNING_SECRET || "dev-secret";
+const maxEdgeValiditySeconds = 60;
+
+export interface SignedSessionToken {
+  token: string;
+}
+
+export interface SessionData {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+export const createSignedSession = (
+  sessionId: string,
+  userId: string,
+  ttlSeconds: number = 3600,
+): SignedSessionToken => {
+  const now = Math.floor(Date.now() / 1000);
+  const payload: SessionData = {
+    sessionId,
+    userId,
+    issuedAt: now,
+    expiresAt: now + ttlSeconds,
+  };
+
+  const payloadStr = JSON.stringify(payload);
+  const signature = crypto
+    .createHmac("sha256", secret)
+    .update(payloadStr)
+    .digest("hex");
+
+  const token = `${Buffer.from(payloadStr).toString("base64")}.${signature}`;
+  return { token };
+};
+
+export const verifySignedSession = (token: string): SessionData | null => {
+  try {
+    const [payloadB64, signature] = token.split(".");
+    if (!payloadB64 || !signature) return null;
+
+    const payloadStr = Buffer.from(payloadB64, "base64").toString("utf-8");
+    const expectedSignature = crypto
+      .createHmac("sha256", secret)
+      .update(payloadStr)
+      .digest("hex");
+
+    if (signature !== expectedSignature) return null;
+
+    const payload = JSON.parse(payloadStr) as SessionData;
+    const now = Math.floor(Date.now() / 1000);
+
+    if (payload.expiresAt < now) return null;
+
+    return payload;
+  } catch {
+    return null;
+  }
+};
+
+export const verifySignedSessionForEdge = (token: string): SessionData | null => {
+  const sessionData = verifySignedSession(token);
+  if (!sessionData) return null;
+
+  const now = Math.floor(Date.now() / 1000);
+  const age = now - sessionData.issuedAt;
+
+  if (age > maxEdgeValiditySeconds) {
+    return null;
+  }
+
+  return sessionData;
+};
